-- Venue Live Guest "Hari Guru Nasional". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara guru), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'guru', 'Hari Guru Nasional (25 November)', 'guru', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 122, 'center 38%',
  $t${"name":"Hari Guru","orn":"diamond","ui":{"ivory":"#FBF3E2","white":"#FFFFFF","soft":"#EEDFF2","soft2":"#C9A8D8","accent":"#5B2A86","deep":"#2E1347","ink":"#2A1636","mute":"#7A6488","line":"#DCC8E6","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#FFFAF0","ink":"#2A1636","accent":"#5B2A86","gold":"#C9A227","leaf":"#EEDFF2","hbg":"rgba(251,243,226,.94)","hline":"#C9A8D8","motif":"diamond"},"hud":{"bg":"rgba(46,19,71,.86)","acc":"#F2D98A","on":"#2A1636"},"scr":{"wine":"#2E1347","veil":"251,243,226"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'guru');
update public.live_venues set decor = $d${"speakers":{"url":"/assets/live-decor/guru/speakers.webp","w":2.2},"balloons":{"url":"/assets/live-decor/guru/balloons.webp","w":1.6},"stall_snacks":{"url":"/assets/live-decor/guru/stall_snacks.webp","w":2.0},"stall_candy":{"url":"/assets/live-decor/guru/stall_candy.webp","w":1.4},"stall_drinks":{"url":"/assets/live-decor/guru/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/guru/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/guru/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/guru/arch.webp"},"fountain":{"url":"/assets/live-decor/guru/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/guru/sign.webp","w":1.5},"easel":{"url":"/assets/live-decor/guru/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/guru/table.webp"},"banner":{"url":"/assets/live-decor/guru/banner.webp","w":1.3},"gifts":{"url":"/assets/live-decor/guru/gifts.webp","w":1.8},"av_host":{"url":"/assets/live-decor/guru/av_host.webp","name":"Pak Guru Batik"},"av_l1":{"url":"/assets/live-decor/guru/av_l1.webp","name":"Pak Guru Batik"},"av_l2":{"url":"/assets/live-decor/guru/av_l2.webp","name":"Pak Guru Blazer"},"av_l3":{"url":"/assets/live-decor/guru/av_l3.webp","name":"Pak Guru Rompi"},"av_l4":{"url":"/assets/live-decor/guru/av_l4.webp","name":"Pak Guru Peci"},"av_p1":{"url":"/assets/live-decor/guru/av_p1.webp","name":"Bu Guru Buket"},"av_p2":{"url":"/assets/live-decor/guru/av_p2.webp","name":"Bu Guru Rok Ungu"},"av_p3":{"url":"/assets/live-decor/guru/av_p3.webp","name":"Bu Guru Hijab"}}$d$::jsonb, background_url = '/assets/live-decor/guru/painting.webp', active = true, updated_at = now() where key = 'guru';
